SQL_DOC.P_SQL:
DECLARE V_CNT NUMBER;
BEGIN SELECT COUNT(*) INTO V_CNT FROM STX_MRO_SHIPMENT_DATE_T@STXMFG WHERE 1 = 1 AND PO_NO = $PO_NO$ AND PO_HEADER_ID = $PO_HEADER_ID$ AND PO_LINE_ID = $PO_LINE_ID$ AND PO_LINE_LOCATION_ID = $PO_LINE_LOCATION_ID$ AND PO_DISTRIBUTION_ID = $PO_DISTRIBUTION_ID$ AND SHIPMENT_DATE = $SHIPMENT_DATE$ ;
IF V_CNT = 0 THEN INSERT INTO STX_MRO_SHIPMENT_DATE_T@STXMFG PO_NO, PO_HEADER_ID, PO_LINE_ID, PO_LINE_LOCATION_ID, PO_DISTRIBUTION_ID, PART_CD, SHIPMENT_QTY, SHIPMENT_DATE, ACCEPT_FLAG, CREATION_DATE, CREATE_BY, LAST_UPDATE_DATE, LAST_UPDATE_BY ) VALUES ( $PO_NO$, $PO_HEADER_ID$, $PO_LINE_ID$, $PO_LINE_LOCATION_ID$, $PO_DISTRIBUTION_ID$, $PART_CD$, $SHIPMENT_QTY$, $SHIPMENT_DATE$, 'N', SYSDATE, '-1', SYSDATE, '-1' ); ELSE UPDATE STX_MRO_SHIPMENT_DATE_T@STXMFG SET ACCEPT_FLAG = 'N', PART_CD = $PART_CD$, SHIPMENT_QTY = $SHIPMENT_QTY$ WHERE 1 = 1 AND PO_NO = $PO_NO$ AND PO_HEADER_ID = $PO_HEADER_ID$ AND PO_LINE_ID = $PO_LINE_ID$ AND PO_LINE_LOCATION_ID = $PO_LINE_LOCATION_ID$ AND PO_DISTRIBUTION_ID = $PO_DISTRIBUTION_ID$ AND SHIPMENT_DATE = $SHIPMENT_DATE$ ; END IF;
END;
